static void mCD_set_number_str(char* str, u8 num) {
    int n = num;
    int f = FALSE;
    int fig_table[3];
    int i;

    bzero(fig_table, sizeof(fig_table));

    for (i = 0; i < 3; i++) {
        const int remain = n % 10;
        const int div = n / 10;

        fig_table[i] = remain;
        n = div;
    }

    for (i = 2; i > 0; i--) {
        if (fig_table[i] > 0 || f == TRUE) {
            *str++ = fig_table[i] + '0';
            f = TRUE;
        }
    }

    *str = fig_table[0] + '0';
}

