void Skin_Matrix_MulMatrix(MtxF *mfA, MtxF *mfB, MtxF *dest) {
    f32 temp_f0;
    f32 temp_f0_2;
    f32 temp_f1;
    f32 temp_f1_2;
    f32 temp_f2;
    f32 temp_f2_2;
    f32 temp_f3;
    f32 temp_f4;
    f32 temp_f4_2;
    f32 temp_f5;
    f32 temp_f5_2;
    f32 temp_f6;
    f32 temp_f6_2;
    f32 temp_f7;
    f32 temp_f7_2;
    f32 temp_f7_3;

    temp_f0 = mfA->mf[0][0];
    temp_f1 = mfA->mf[1][0];
    temp_f2 = mfA->mf[2][0];
    temp_f3 = mfA->mf[3][0];
    dest->mf[0][0] = (temp_f3 * mfB->mf[0][3]) + ((temp_f2 * mfB->mf[0][2]) + ((temp_f0 * mfB->mf[0][0]) + (temp_f1 * mfB->mf[0][1])));
    dest->mf[1][0] = (temp_f3 * mfB->mf[1][3]) + ((temp_f2 * mfB->mf[1][2]) + ((temp_f0 * mfB->mf[1][0]) + (temp_f1 * mfB->mf[1][1])));
    dest->mf[2][0] = (temp_f3 * mfB->mf[2][3]) + ((temp_f2 * mfB->mf[2][2]) + ((temp_f0 * mfB->mf[2][0]) + (temp_f1 * mfB->mf[2][1])));
    dest->mf[3][0] = (temp_f3 * mfB->mf[3][3]) + ((temp_f2 * mfB->mf[3][2]) + ((temp_f0 * mfB->mf[3][0]) + (temp_f1 * mfB->mf[3][1])));
    temp_f4 = mfA->mf[0][1];
    temp_f5 = mfA->mf[1][1];
    temp_f6 = mfA->mf[2][1];
    temp_f7 = mfA->mf[3][1];
    dest->mf[0][1] = (temp_f7 * mfB->mf[0][3]) + ((temp_f6 * mfB->mf[0][2]) + ((temp_f4 * mfB->mf[0][0]) + (temp_f5 * mfB->mf[0][1])));
    dest->mf[1][1] = (temp_f7 * mfB->mf[1][3]) + ((temp_f6 * mfB->mf[1][2]) + ((temp_f4 * mfB->mf[1][0]) + (temp_f5 * mfB->mf[1][1])));
    dest->mf[2][1] = (temp_f7 * mfB->mf[2][3]) + ((temp_f6 * mfB->mf[2][2]) + ((temp_f4 * mfB->mf[2][0]) + (temp_f5 * mfB->mf[2][1])));
    dest->mf[3][1] = (temp_f7 * mfB->mf[3][3]) + ((temp_f6 * mfB->mf[3][2]) + ((temp_f4 * mfB->mf[3][0]) + (temp_f5 * mfB->mf[3][1])));
    temp_f4_2 = mfA->mf[0][2];
    temp_f5_2 = mfA->mf[1][2];
    temp_f6_2 = mfA->mf[2][2];
    temp_f7_2 = mfA->mf[3][2];
    dest->mf[0][2] = (temp_f7_2 * mfB->mf[0][3]) + ((temp_f6_2 * mfB->mf[0][2]) + ((temp_f4_2 * mfB->mf[0][0]) + (temp_f5_2 * mfB->mf[0][1])));
    dest->mf[1][2] = (temp_f7_2 * mfB->mf[1][3]) + ((temp_f6_2 * mfB->mf[1][2]) + ((temp_f4_2 * mfB->mf[1][0]) + (temp_f5_2 * mfB->mf[1][1])));
    dest->mf[2][2] = (temp_f7_2 * mfB->mf[2][3]) + ((temp_f6_2 * mfB->mf[2][2]) + ((temp_f4_2 * mfB->mf[2][0]) + (temp_f5_2 * mfB->mf[2][1])));
    dest->mf[3][2] = (temp_f7_2 * mfB->mf[3][3]) + ((temp_f6_2 * mfB->mf[3][2]) + ((temp_f4_2 * mfB->mf[3][0]) + (temp_f5_2 * mfB->mf[3][1])));
    temp_f7_3 = mfA->mf[0][3];
    temp_f0_2 = mfA->mf[1][3];
    temp_f1_2 = mfA->mf[2][3];
    temp_f2_2 = mfA->mf[3][3];
    dest->mf[0][3] = (temp_f2_2 * mfB->mf[0][3]) + ((temp_f1_2 * mfB->mf[0][2]) + ((temp_f7_3 * mfB->mf[0][0]) + (temp_f0_2 * mfB->mf[0][1])));
    dest->mf[1][3] = (temp_f2_2 * mfB->mf[1][3]) + ((temp_f1_2 * mfB->mf[1][2]) + ((temp_f7_3 * mfB->mf[1][0]) + (temp_f0_2 * mfB->mf[1][1])));
    dest->mf[2][3] = (temp_f2_2 * mfB->mf[2][3]) + ((temp_f1_2 * mfB->mf[2][2]) + ((temp_f7_3 * mfB->mf[2][0]) + (temp_f0_2 * mfB->mf[2][1])));
    dest->mf[3][3] = (temp_f2_2 * mfB->mf[3][3]) + ((temp_f1_2 * mfB->mf[3][2]) + ((temp_f7_3 * mfB->mf[3][0]) + (temp_f0_2 * mfB->mf[3][1])));
}

