    bg2XOffset = gBgInfo[2].hOfs - gEntityInfo[slot].xPosScreen;
    bg2YOffset = gBgInfo[2].vOfs - gEntityInfo[slot].yPosScreen;

    xPos = (bg2XOffset * gBg2XMag) / 0x100;
