            yPos = gBgInfo[2].vOfs - yPos + ((0x100 - gBg2YMag) >> 6);
            break;

        default:
            yPos = gBgInfo[2].vOfs - yPos + ((0x100 - gBg2YMag) >> 4);
            break;
    }

    gEntityInfo[slot].xPosScreen = xPos;
    gEntityInfo[slot].yPosScreen = yPos;
}

