s16 MultiplyQ8(s16 num1, s16 num2)
{
    s32 result;

    result = num1 * num2;
    result /= 0x100;
    return result;
}

m2c.source:
s16 MultiplyQ8(s16 num1, s16 num2) {
    s32 temp_r0;
    s32 var_r1;

    temp_r0 = num1 * num2;
    var_r1 = temp_r0;
    if (temp_r0 < 0) {
        var_r1 += 0xFF;
    }
    return (s16) ((s32) (var_r1 << 8) >> 0x10);
}

