void mtxRot(Mtx mtx, float x, float y, float z) {
    Mtx rotY;
    Mtx rotZ;

    if (x != 0.0f) {
        MTXRotRad(mtx, 'X', MTXDegToRad(x));
    } else {
        MTXIdentity(mtx);
    }
    if (y != 0.0f) {
        MTXRotRad(rotY, 'Y', MTXDegToRad(y));
        MTXConcat(rotY, mtx, mtx);
    }
    if (z != 0.0f) {
        MTXRotRad(rotZ, 'Z', MTXDegToRad(z));
        MTXConcat(rotZ, mtx, mtx);
    }
}

