void mtxRot(f32 (*mtx)[4], f32 x, f32 y, f32 z) {
    if (x != 0.0f) {
        PSMTXRotRad(mtx, 0x58, 0.017453292f * x);
    } else {
        PSMTXIdentity(mtx);
    }
    if (y != 0.0f) {
        PSMTXRotRad((f32 (*)[4]) &sp38[0], 0x59, 0.017453292f * y);
        PSMTXConcat((f32 (*)[4]) &sp38[0], mtx, mtx);
    }
    if (z != 0.0f) {
        PSMTXRotRad((f32 (*)[4]) &sp8[0], 0x5A, 0.017453292f * z);
        PSMTXConcat((f32 (*)[4]) &sp8[0], mtx, mtx);
    }
}

