int TexImg::calcDataSize(int format, int width, int height)
{
	s32 size = 0;

	switch (format) {
	case TEX_FMT_S3TC:
	{
		size = (width * height / 8) * 4;
		break;
	}
	case TEX_FMT_RGB5A3:
	{
		size = width * height * 2;
		break;
	}
	case TEX_FMT_RGB565:
	{
		size = width * height * 2;
		break;
	}
	case TEX_FMT_I4:
	{
		size = width * height / 2;
		break;
	}
	case TEX_FMT_I8:
	{
		size = width * height;
		break;
	}
	case TEX_FMT_IA4:
	{
		size = width * height;
		break;
	}
	case TEX_FMT_IA8:
	{
		size = width * height * 2;
		break;
	}
	case TEX_FMT_RGBA8:
	{
		size = width * height * 4;
		break;
	}
	case TEX_FMT_Z8:
	{
		size = width * height;
		break;
	}
	case TEX_FMT_COUNT: // what?
	{
		size = width * height;
		break;
	}
	}

	return size;
}

