bool KRect::inside(immut Vector3f& point)
{
	Vector3f rectMin = mBotTri.Origin();

	Vector3f rectMax;
	rectMax = (mBotTri.Origin() + mBotTri.Edge0()) + mBotTri.Edge1();

	if (point.x >= rectMin.x && point.x <= rectMax.x && point.z >= rectMin.z && point.z <= rectMax.z) {
		return true;
	}

	return false;
}

